-- 447: Original BrillaPrep WASSCE Core Mathematics sprint 2 beta questions, part 5 of 10 (batch wassce-core-math-sprint2-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_447_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_447_guard;
INSERT INTO _migration_447_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_021' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Express 2.5% as a fraction in its lowest terms.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1/4","B. 1/25","C. 1/40","D. 1/400"]' AND q.correct_answer IS 'C' AND q.explanation IS '2.5% = 2.5/100 = 25/1000. Dividing the numerator and denominator by 25 gives 1/40. (1/400 would be 0.25%, ten times smaller.) Therefore the correct answer is C: 1/40.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Express' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_021' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_447_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_022' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A trader buys a bicycle for GH₵400.00 and sells it at a loss of 15%. Find the selling price.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. GH₵60.00","B. GH₵385.00","C. GH₵460.00","D. GH₵340.00"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The loss is 15% of 400 = (15/100) × 400 = GH₵60.00, so the selling price is 400 − 60 = GH₵340.00. (GH₵60.00 is the loss itself, not the selling price.) Therefore the correct answer is D: GH₵340.00.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_022' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_447_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_023' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the compound interest on GH₵5,000.00 invested at 10% per annum for 2 years.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'GH₵1,050.00' AND q.explanation IS 'After the first year the amount is 5,000 × 1.10 = GH₵5,500.00. After the second year it is 5,500 × 1.10 = GH₵6,050.00. The compound interest is 6,050 − 5,000 = GH₵1,050.00. Answer: GH₵1,050.00.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_023' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_447_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_024' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A machine valued at GH₵8,000.00 depreciates by 25% each year. Calculate its value after 2 years.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'GH₵4,500.00' AND q.explanation IS 'Each year the value is multiplied by (100 − 25)/100 = 0.75. After the first year: 8,000 × 0.75 = GH₵6,000.00. After the second year: 6,000 × 0.75 = GH₵4,500.00. Equivalently, 8,000 × 0.75² = 8,000 × 0.5625 = GH₵4,500.00. Answer: GH₵4,500.00.' AND q.difficulty IS 'hard' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_024' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_447_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_025' AND NOT (q.topic_id IS 'topic_wassce_p2_math_men' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the area of a rectangle with length 14 cm and width 6 cm.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 84 cm²","B. 20 cm²","C. 40 cm²","D. 168 cm²"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Area of a rectangle = length × width = 14 × 6 = 84 cm². (40 cm is the perimeter 2(14 + 6), a common mix-up.) Therefore the correct answer is A: 84 cm².' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_025' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_021', 'topic_wassce_p2_math_num', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Express 2.5% as a fraction in its lowest terms.', 'multiple_choice', NULL, '["A. 1/4","B. 1/25","C. 1/40","D. 1/400"]', 'C', '2.5% = 2.5/100 = 25/1000. Dividing the numerator and denominator by 25 gives 1/40. (1/400 would be 0.25%, ten times smaller.) Therefore the correct answer is C: 1/40.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Express', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_022', 'topic_wassce_p2_math_num', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A trader buys a bicycle for GH₵400.00 and sells it at a loss of 15%. Find the selling price.', 'multiple_choice', NULL, '["A. GH₵60.00","B. GH₵385.00","C. GH₵460.00","D. GH₵340.00"]', 'D', 'The loss is 15% of 400 = (15/100) × 400 = GH₵60.00, so the selling price is 400 − 60 = GH₵340.00. (GH₵60.00 is the loss itself, not the selling price.) Therefore the correct answer is D: GH₵340.00.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_023', 'topic_wassce_p2_math_num', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Calculate the compound interest on GH₵5,000.00 invested at 10% per annum for 2 years.', 'calculation', NULL, NULL, 'GH₵1,050.00', 'After the first year the amount is 5,000 × 1.10 = GH₵5,500.00. After the second year it is 5,500 × 1.10 = GH₵6,050.00. The compound interest is 6,050 − 5,000 = GH₵1,050.00. Answer: GH₵1,050.00.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_024', 'topic_wassce_p2_math_num', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A machine valued at GH₵8,000.00 depreciates by 25% each year. Calculate its value after 2 years.', 'calculation', NULL, NULL, 'GH₵4,500.00', 'Each year the value is multiplied by (100 − 25)/100 = 0.75. After the first year: 8,000 × 0.75 = GH₵6,000.00. After the second year: 6,000 × 0.75 = GH₵4,500.00. Equivalently, 8,000 × 0.75² = 8,000 × 0.5625 = GH₵4,500.00. Answer: GH₵4,500.00.', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_025', 'topic_wassce_p2_math_men', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Calculate the area of a rectangle with length 14 cm and width 6 cm.', 'multiple_choice', NULL, '["A. 84 cm²","B. 20 cm²","C. 40 cm²","D. 168 cm²"]', 'A', 'Area of a rectangle = length × width = 14 × 6 = 84 cm². (40 cm is the perimeter 2(14 + 6), a common mix-up.) Therefore the correct answer is A: 84 cm².', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO1', NULL, NULL, 'board_waec');
